async function visitLedger(stream, visitor) {
  const reader = stream.getReader();
  const decoder = new TextDecoder("utf-8");
  let accepted = 0;
  let rejected = 0;
  let line = 0;
  let buffer = "";
  let stopped = false;
  let normalEOF = false;

  const visitLine = async (text) => {
    line++;

    if (/^[ \t\r]*$/.test(text)) {
      return;
    }

    let value;
    try {
      value = JSON.parse(text);
    } catch {
      rejected++;
      return;
    }

    accepted++;
    if ((await visitor({ line, value })) === false) {
      stopped = true;
    }
  };

  try {
    while (!stopped) {
      const result = await reader.read();

      if (result.done) {
        buffer += decoder.decode();

        if (buffer.length > 0) {
          await visitLine(buffer);
          buffer = "";
        }

        normalEOF = true;
        break;
      }

      buffer += decoder.decode(result.value, { stream: true });

      let newline;
      while (!stopped && (newline = buffer.indexOf("\n")) !== -1) {
        const currentLine = buffer.slice(0, newline);
        buffer = buffer.slice(newline + 1);
        await visitLine(currentLine);
      }
    }

    if (stopped) {
      await reader.cancel();
    }

    return { accepted, rejected, stopped };
  } catch (error) {
    await reader.cancel();
    throw error;
  } finally {
    reader.releaseLock();
  }
}
